import streamlit as st
import base64, io, os
from datetime import date
from docx import Document
from docx.shared import Pt, Inches, Emu
from docx.enum.text import WD_ALIGN_PARAGRAPH

# ── Logos embutidas ───────────────────────────────────────────────────────
HEADER_B64 = ""
FOOTER_B64 = ""

MESES = {1:"janeiro",2:"fevereiro",3:"marco",4:"abril",5:"maio",6:"junho",
         7:"julho",8:"agosto",9:"setembro",10:"outubro",11:"novembro",12:"dezembro"}

def data_extenso():
    h = date.today()
    return "Palmas/TO, {:02d} de {} de {}.".format(h.day, MESES[h.month], h.year)

def add_run(para, text, bold=False, italic=False, size_pt=12, font_name=None):
    r = para.add_run(text)
    r.bold = bold
    r.italic = italic
    r.font.size = Pt(size_pt)
    if font_name:
        r.font.name = font_name

def add_img(para, b64_str, width_inches=6.3):
    buf = io.BytesIO(base64.b64decode(b64_str))
    para.add_run().add_picture(buf, width=Inches(width_inches))

def spacer(doc, n=1):
    for _ in range(n):
        p = doc.add_paragraph()
        p.paragraph_format.space_before = Pt(0)
        p.paragraph_format.space_after  = Pt(0)

def gerar_docx(nome, cpf_cnpj, endereco, tipo, rg, nacionalidade, estado_civil):
    doc = Document()
    sec = doc.sections[0]
    sec.page_width    = Emu(7773670)
    sec.page_height   = Emu(12803505)
    sec.top_margin    = Emu(1108710)
    sec.bottom_margin = Emu(1080135)
    sec.left_margin   = Emu(1080135)
    sec.right_margin  = Emu(1080135)

    hdr = sec.header.paragraphs[0]
    hdr.alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_img(hdr, HEADER_B64)

    ftr = sec.footer.paragraphs[0]
    ftr.alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_img(ftr, FOOTER_B64)

    spacer(doc, 3)

    titulo = doc.add_paragraph()
    titulo.alignment = WD_ALIGN_PARAGRAPH.CENTER
    titulo.paragraph_format.space_before = Pt(0)
    titulo.paragraph_format.space_after  = Pt(0)
    add_run(titulo, "PROCURACAO", bold=True, size_pt=16)

    spacer(doc, 2)

    p = doc.add_paragraph()
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after  = Pt(0)
    add_run(p, "OUTORGANTE: ", bold=True)
    spacer(doc)

    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after  = Pt(0)
    add_run(p, nome.upper(), bold=True)
    if tipo == "pj":
        add_run(p, ", pessoa juridica de direito privado, inscrita no CNPJ n. "
                   + cpf_cnpj + ", com sede a " + endereco + ".")
    else:
        trecho = ", " + nacionalidade
        if estado_civil:
            trecho += ", " + estado_civil
        if rg:
            trecho += ", portador(a) do RG n. " + rg + " e CPF n. " + cpf_cnpj
        else:
            trecho += ", inscrito(a) no CPF n. " + cpf_cnpj
        trecho += ", residente e domiciliado(a) em " + endereco + "."
        add_run(p, trecho)

    spacer(doc)

    p = doc.add_paragraph()
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after  = Pt(0)
    add_run(p, "OUTORGADO: ")
    spacer(doc)

    p2 = doc.add_paragraph()
    p2.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p2.paragraph_format.space_before = Pt(0)
    p2.paragraph_format.space_after  = Pt(0)
    add_run(p2, "JULIO FRANCO POLI, ", bold=True)
    add_run(p2, "advogado, inscrito na OAB/TO, sob o n.o 4.589B, domiciliado "
                "profissionalmente na Qd. 106 Norte, Al. 02, Conj. L, Lote 04/05, "
                "Ed. Palmas Business Center, Sala 905, Palmas - TO. Fones: (63) 98462-4630.")
    spacer(doc)

    p = doc.add_paragraph()
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after  = Pt(0)
    add_run(p, "PODERES:")
    spacer(doc)

    p3 = doc.add_paragraph()
    p3.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p3.paragraph_format.space_before = Pt(0)
    p3.paragraph_format.space_after  = Pt(0)
    add_run(p3, "Todos os da clausula ")
    add_run(p3, "ad judicia", italic=True)
    add_run(p3, " e para o foro em geral, podendo para tanto propor e acompanhar "
                "acoes, em qualquer juizo, Instancia ou Tribunal, contestar, reconvir, "
                "opor embargos, intervir como assistente ou litisconsorte, executar, "
                "embargar, requerer falencia e promover todas as medidas preventivas, "
                "firmar acordos, desistir, receber e dar quitacao, transigir, produzir "
                "provas, levantar alvara/RPV e representar a outorgante em qualquer "
                "reparticao publica federal, estadual ou municipal e suas autarquias.")

    spacer(doc, 4)

    p_data = doc.add_paragraph()
    p_data.paragraph_format.space_before = Pt(0)
    p_data.paragraph_format.space_after  = Pt(0)
    add_run(p_data, data_extenso(), font_name="Times New Roman")

    spacer(doc, 4)

    p_ass = doc.add_paragraph()
    p_ass.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p_ass.paragraph_format.space_before = Pt(0)
    p_ass.paragraph_format.space_after  = Pt(0)
    add_run(p_ass, nome.upper(), bold=True)

    buf = io.BytesIO()
    doc.save(buf)
    buf.seek(0)
    return buf


# ── Interface Streamlit ───────────────────────────────────────────────────

st.set_page_config(
    page_title="Procuracao - Julio Franco Poli",
    page_icon="⚖️",
    layout="centered"
)

st.markdown("""
<style>
    .stApp { max-width: 750px; margin: auto; }
    h1 { color: #1a3a5c; }
    .stButton>button { background-color: #1a3a5c; color: white; border-radius: 6px;
                       padding: 0.5rem 2rem; font-size: 1rem; width: 100%; }
    .stButton>button:hover { background-color: #2d5a8e; }
</style>
""", unsafe_allow_html=True)

st.title("⚖️ Gerador de Procuração")
st.caption("Julio Franco Poli Advocacia • OAB/TO n.º 4.589B")
st.divider()

tipo = st.radio("Tipo do outorgante", ["Pessoa Jurídica", "Pessoa Física"], horizontal=True)
tipo_key = "pj" if tipo == "Pessoa Jurídica" else "pf"

st.subheader("Dados do Outorgante")
col1, col2 = st.columns(2)

with col1:
    nome = st.text_input("Nome / Razão Social *")

with col2:
    if tipo_key == "pj":
        cpf_cnpj = st.text_input("CNPJ *", placeholder="00.000.000/0001-00")
        rg = None
        nacionalidade = "brasileiro(a)"
        estado_civil = ""
    else:
        cpf_cnpj = st.text_input("CPF *", placeholder="000.000.000-00")

if tipo_key == "pf":
    col3, col4 = st.columns(2)
    with col3:
        rg = st.text_input("RG", placeholder="Deixe em branco se não houver")
        rg = rg if rg.strip() else None
    with col4:
        nacionalidade = st.text_input("Nacionalidade", value="brasileiro(a)")
    estado_civil = st.text_input("Estado civil", placeholder="solteiro(a), casado(a)... (opcional)")

endereco = st.text_input("Endereço completo *", placeholder="Rua, número, bairro, cidade - UF, CEP")

st.divider()

if st.button("📄 Gerar Procuração"):
    if not nome.strip():
        st.error("Informe o nome / razão social.")
    elif not cpf_cnpj.strip():
        st.error("Informe o CPF/CNPJ.")
    elif not endereco.strip():
        st.error("Informe o endereço.")
    else:
        with st.spinner("Gerando documento..."):
            buf = gerar_docx(
                nome=nome.strip(),
                cpf_cnpj=cpf_cnpj.strip(),
                endereco=endereco.strip(),
                tipo=tipo_key,
                rg=rg,
                nacionalidade=nacionalidade if tipo_key=="pf" else "",
                estado_civil=estado_civil.strip() if tipo_key=="pf" else "",
            )
        nome_arquivo = "Procuracao_" + nome.strip().replace(" ","_")[:40] + ".docx"
        st.success("Procuração gerada com sucesso!")
        st.download_button(
            label="⬇️ Baixar Procuração (.docx)",
            data=buf,
            file_name=nome_arquivo,
            mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document"
        )
